sys.addaudithook(deny)
from friday_commands import CommandArgument,CommandSpec,CommandRequest,CommandExecution,NoData,HelpData,ExitData,CommandOutcome,CommandError,DispatchResult,CommandRegistry
count=0
def require(c,m):
 global count
 if not c:raise RuntimeError(m)
 count+=1
def raises(kind,call):
 try:call()
 except BaseException as e:require(type(e) is kind,'incorrect boundary '+repr(type(e)))
 else:raise RuntimeError('required exception missing')
class ProbeFailure(Exception):pass
failure=ProbeFailure('caller iteration failed')
class Broken:
 def __iter__(self):raise failure
# Field order precedes later invalid fields and iterator access.
raises(TypeError,lambda:CommandSpec(1,'d','c','u',Broken(),(),7))
try:CommandSpec('x','d','c','u',Broken(),(),7)
