class ExitSubclass(ExitData):pass
raises(TypeError,lambda:CommandOutcome(data=HelpSubclass(())))
raises(TypeError,lambda:CommandOutcome(data=ExitSubclass()))
class Text(str):pass
require(CommandExecution(Text(' x ')).session_id==' x ','string subclasses preserved')
# Registration preserves unusual valid identifiers and never double-normalizes.
async def checks():
 calls=[]
 async def record(request,execution):
  calls.append(request)
  return CommandOutcome(data=NoData())
 r=CommandRegistry();r.register(CommandSpec(' /Odd ', ' D ',' C ',' U ',[' /Alias '], [CommandArgument(' X ',' D ',True,'raw',[' Z '])], ' raw\n'),record)
 require(r.names()==frozenset({'/odd','/alias'}),'one-pass registration')
 before=(r.names(),r.specs()); canonical=r.resolve(' /Odd ')
 require(canonical is r.resolve(' /Alias '),'shared canonical identity')
 require(canonical.detail==' raw\n' and canonical.arguments[0].name==' X ','raw metadata preserved')
 raises(ValueError,lambda:r.register(CommandSpec('new','D','C','U',['fresh',' /ALIAS ']),record))
 require((r.names(),r.specs())==before and r.resolve('fresh') is None,'atomic alias collision')
 result=await r.execute_text('///ODD\t"A\u2003B"',CommandExecution())
 require(result.handled and calls[-1].name=='/odd' and calls[-1].args==('"A','B"'),'Unicode whitespace and quoted fragments')
 require(calls[-1].spec is canonical,'request canonical identity')
 unknown=await r.execute_text('//ODD',CommandExecution())
 require(unknown.outcome.error.command_name=='odd' and len(calls)==1,'parsed key not re-normalized')
 ordinary=await r.execute_text('\n/odd',CommandExecution());require(not ordinary.handled and len(calls)==1,'literal leading slash')
 # Synchronous call exceptions and await-stage exceptions propagate unchanged.
 for phase in ('call','await'):
  hits=[];awaits=[];err=ProbeFailure(phase)
  class Result:
   def __await__(self):
    awaits.append(1)
    async def fail():raise err
    return fail().__await__()
  class Handler:
   def __call__(self,request,execution):
    hits.append(request)
